-- RCAA Era Ball v1.6 multiplayer upgrade

alter table public.lobbies add column if not exists current_round integer not null default 0;
alter table public.lobbies add column if not exists game_state jsonb not null default '{}'::jsonb;
alter table public.lobbies add column if not exists winner_id uuid references auth.users(id) on delete set null;
alter table public.lobbies add column if not exists completed_at timestamptz;

alter table public.lobby_players add column if not exists current_roll jsonb;
alter table public.lobby_players add column if not exists chemistry numeric not null default 0;
alter table public.lobby_players add column if not exists last_action_at timestamptz not null default now();

create table if not exists public.duel_picks (
  id bigint generated by default as identity primary key,
  lobby_id uuid not null references public.lobbies(id) on delete cascade,
  user_id uuid not null references auth.users(id) on delete cascade,
  round_number integer not null check (round_number between 1 and 4),
  card_key text not null references public.rcaa_players(card_key),
  player_snapshot jsonb not null,
  created_at timestamptz not null default now(),
  unique(lobby_id,user_id,round_number)
);

create index if not exists duel_picks_lobby_idx on public.duel_picks(lobby_id);
create index if not exists duel_picks_user_idx on public.duel_picks(user_id);

alter table public.duel_picks enable row level security;
drop policy if exists "authenticated read duel picks" on public.duel_picks;
create policy "authenticated read duel picks" on public.duel_picks for select to authenticated using (true);

do $$ begin
  alter publication supabase_realtime add table public.duel_picks;
exception when duplicate_object then null; end $$;

-- Fantasy is seven rounds (28 total picks). Keep the legacy RPC compatible.
create or replace function public.make_fantasy_pick(p_lobby_id uuid, p_card_key text)
returns public.fantasy_picks
language plpgsql security definer set search_path='' as $$
declare
  target public.lobbies%rowtype; card public.rcaa_players%rowtype; player_count integer;
  round_index integer; seat_offset integer; expected_index integer; expected_user uuid;
  inserted public.fantasy_picks%rowtype; total_picks integer;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  select * into target from public.lobbies where id=p_lobby_id for update;
  if target.id is null or target.mode<>'fantasy' or target.status<>'drafting' then raise exception 'Draft is not active'; end if;
  player_count := array_length(target.draft_order,1);
  if player_count<>4 then raise exception 'Four players are required'; end if;
  total_picks := player_count*7;
  if target.current_pick>=total_picks then raise exception 'Draft is complete'; end if;
  round_index := target.current_pick/player_count; seat_offset := target.current_pick%player_count;
  expected_index := case when round_index%2=0 then seat_offset+1 else player_count-seat_offset end;
  expected_user := target.draft_order[expected_index];
  if expected_user<>auth.uid() then raise exception 'It is not your turn'; end if;
  select * into card from public.rcaa_players where card_key=p_card_key;
  if card.card_key is null then raise exception 'Unknown player card'; end if;
  values(target.id,target.current_pick+1,round_index+1,auth.uid(),card.card_key,card.player_data) returning * into inserted;
  update public.lobbies set current_pick=current_pick+1,status=case when current_pick+1>=total_picks then 'lineup' else status end where id=target.id;
  return inserted;
end $$;

-- Refresh the authoritative catalog to v1.6 / v1.052 ratings and cards.
on conflict(card_key) do update set season=excluded.season, team_code=excluded.team_code, player_name=excluded.player_name, adp=excluded.adp, player_data=excluded.player_data;

